using System.Collections.Generic;public class Solution{class N{public N[]c=new N[26];public string w;}List<string>o=new();void F(char[][]b,int i,int j,N p){if(i<0||j<0||i==b.Length||j==b[0].Length||b[i][j]=='#')return;p=p.c[b[i][j]-'a'];if(p==null)return;if(p.w!=null){o.Add(p.w);p.w=null;}char c=b[i][j];b[i][j]='#';F(b,i+1,j,p);F(b,i-1,j,p);F(b,i,j+1,p);F(b,i,j-1,p);b[i][j]=c;}public IList<string> FindWords(char[][]b,string[]w){var r=new N();foreach(var s in w){var p=r;foreach(char c in s){int k=c-'a';if(p.c[k]==null)p.c[k]=new N();p=p.c[k];}p.w=s;}for(int i=0;i<b.Length;i++)for(int j=0;j<b[0].Length;j++)F(b,i,j,r);return o;}}
